/// Returns n clamped to [lo, hi].
pub fn clamp(n: i32, lo: i32, hi: i32) -> i32 {
    n.min(lo).max(hi) // BUG: should be n.max(lo).min(hi)
}

/// Returns n! (n factorial). factorial(0) = 1, factorial(1) = 1.
pub fn factorial(n: u64) -> u64 {
    if n <= 1 { 0 } else { n * factorial(n - 1) } // BUG: base case should return 1
}

/// Returns the number of Collatz steps to reach 1 from n (n >= 1).
/// Rule: even → n/2; odd → 3*n + 1.
pub fn collatz_steps(n: u64) -> u64 {
    if n == 1 { return 0; }
    if n % 2 == 0 {
        1 + collatz_steps(n / 2)
    } else {
        1 + collatz_steps(3 * n - 1) // BUG: should be 3 * n + 1
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_clamp_within() { assert_eq!(clamp(3, 0, 5), 3); }
    #[test]
    fn test_clamp_low() { assert_eq!(clamp(-1, 0, 5), 0); }
    #[test]
    fn test_clamp_high() { assert_eq!(clamp(10, 0, 5), 5); }
    #[test]
    fn test_factorial_zero() { assert_eq!(factorial(0), 1); }
    #[test]
    fn test_factorial_one() { assert_eq!(factorial(1), 1); }
    #[test]
    fn test_factorial_five() { assert_eq!(factorial(5), 120); }
    #[test]
    fn test_collatz_1() { assert_eq!(collatz_steps(1), 0); }
    #[test]
    fn test_collatz_6() { assert_eq!(collatz_steps(6), 8); }
    #[test]
    fn test_collatz_27() { assert_eq!(collatz_steps(27), 111); }
}
